#!/usr/bin/env node
// Agent efficiency report: reads a factory session's Mastra database and
// reports how often the agent hit known check failures (lint, role check),
// with each occurrence collapsible to the full error output.
//
// Usage: node scripts/agent-efficiency-report.mjs [path/to/.factory/mastra.db]
// Writes docs/factory/agent-efficiency-report.md. The file is auto-generated
// and must be committed whenever it changes.

import { DatabaseSync } from 'node:sqlite'
import { mkdirSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'

const CHECKS = [
  { name: 'lint failures', pattern: /\bnx (run-many -t )?lint\b/ },
  { name: 'role check failures', pattern: /\brole.?check\b|role-enforcement/i },
]

const dbPath = resolve(process.argv[2] ?? '.factory/mastra.db')
const db = new DatabaseSync(dbPath, { readOnly: true })

const commandRuns = []

for (const row of db.prepare('SELECT content, "createdAt" FROM mastra_messages ORDER BY "createdAt"').all()) {
  let message
  try {
    message = JSON.parse(row.content)
  } catch {
    continue
  }
  const invocations = new Map()
  for (const part of message.parts ?? []) {
    if (part.type === 'tool-invocation') {
      invocations.set(part.toolInvocation?.toolCallId, part.toolInvocation)
    }
    if (part.type === 'data-sandbox-exit') {
      const invocation = invocations.get(part.data?.toolCallId)
      if (!invocation) continue
      const command = invocation.args?.command
      if (typeof command !== 'string') continue
      commandRuns.push({
        command,
        output: String(invocation.result ?? ''),
        exitCode: part.data.exitCode,
        timestamp: part.createdAt ?? row.createdAt,
      })
    }
  }
}

function failuresFor(check) {
  return commandRuns
    .filter((run) => check.pattern.test(run.command) && run.exitCode !== 0)
    .map((run) => run)
}

const sections = CHECKS.map((check) => ({ check, failures: failuresFor(check) }))

// Strips ANSI escape sequences so the output is readable.
function stripAnsi(text) {
  // eslint-disable-next-line no-control-regex
  return text.replaceAll(/\x1b\[[0-9;]*m/g, '')
}

function failureMarkdown(failure) {
  const time = new Date(failure.timestamp).toISOString()
  return [
    `<details>`,
    `<summary>${time} — exit code ${failure.exitCode}</summary>`,
    '',
    '```text',
    `$ ${failure.command}`,
    '',
    stripAnsi(failure.output) || '(no output)',
    '```',
    '',
    '</details>',
  ].join('\n')
}

function sectionMarkdown(section) {
  const occurrences = section.failures.map(failureMarkdown).join('\n\n')
  return [
    `## ${section.check.name}: ${section.failures.length}`,
    '',
    occurrences || 'No failures found.',
  ].join('\n')
}

const counts = sections
  .map((section) => `- ${section.check.name}: ${section.failures.length}`)
  .join('\n')

const markdown = [
  '# Agent efficiency report',
  '',
  '<!-- Auto-generated by scripts/agent-efficiency-report.mjs. Do not edit by hand. -->',
  '',
  counts,
  '',
  sections.map(sectionMarkdown).join('\n\n'),
  '',
].join('\n')

const outputPath = resolve('docs/factory/agent-efficiency-report.md')
mkdirSync(dirname(outputPath), { recursive: true })
writeFileSync(outputPath, markdown)
console.log(`Report written to ${outputPath}`)
console.log(sections.map((s) => `${s.check.name}: ${s.failures.length}`).join('\n'))
